"""
LoginGuard implements consecutive-failed login throttling.

Policy mapping (NIST SP 800-63B-4 excerpt 3.2.2):
- Limit consecutive failed authentication attempts per account to no more than 100
  by disabling that authenticator.
- A successful authentication resets the consecutive-failure count.

This module uses the provided standard library-only `login_throttle` skill.
"""

from __future__ import annotations

from typing import Dict

import login_throttle


class LoginGuard:
    """Account-level consecutive-failure throttling helper."""

    def __init__(self) -> None:
        self._throttle = login_throttle.Throttle()

    def failed(self, account: str) -> None:
        """Record one consecutive failed attempt for the given account."""
        if not isinstance(account, str):
            raise TypeError("account must be a string")
        if account == "":
            # Keep behavior deterministic; an empty identifier is still a valid key, but
            # it is likely a caller error.
            raise ValueError("account must be a non-empty string")
        self._throttle.record_failure(account)

    def succeeded(self, account: str) -> None:
        """Reset the consecutive-failure count after a successful authentication."""
        if not isinstance(account, str):
            raise TypeError("account must be a string")
        if account == "":
            raise ValueError("account must be a non-empty string")
        self._throttle.record_success(account)

    def locked(self, account: str) -> bool:
        """Return whether the account is currently locked by throttling rules."""
        if not isinstance(account, str):
            raise TypeError("account must be a string")
        if account == "":
            raise ValueError("account must be a non-empty string")
        return self._throttle.is_locked(account)
